/* Chinese Econ JMC — client-side rendering. Data comes from data.js (generated by scripts/build.py). */
(function () {
  "use strict";

  const CONFIG = {
    // Change this to your repository URL after creating it on GitHub.
    repoUrl: "https://github.com/chinese-econ-jmc/chinese-econ-jmc.github.io",
  };

  const D = window.JMC_DATA;
  if (!D) { document.getElementById("tbody").innerHTML = "<tr><td colspan=6>data.js 未找到，请先运行 python scripts/build.py</td></tr>"; return; }

  const $ = (id) => document.getElementById(id);
  const el = {
    tabs: $("cycle-tabs"), stats: $("stats"), q: $("q"), region: $("region"), school: $("school"),
    placement: $("placement"), sort: $("sort"), group: $("group"), reset: $("reset"), chips: $("field-chips"),
    count: $("count"), tbody: $("tbody"), empty: $("empty"), generated: $("generated"), repo: $("repo-link"),
  };
  el.generated.textContent = D.generated;
  el.repo.href = CONFIG.repoUrl;

  const REGION_LABEL = { "美国区域": "美国", "加拿大区域": "加拿大", "非美国区域": "非美国" };
  const PLACE_LABEL = { "Faculty": "教职", "Postdoc": "博后", "Industry & Other": "业界/其他", "Deferred": "延期" };

  // ------------------------------------------------------------ state ----
  const state = {
    cycle: D.cycles[0], q: "", region: "", school: "", placement: "", sort: "rank", group: true,
    fields: new Set(), open: new Set(),
  };

  function readHash() {
    const h = new URLSearchParams(location.hash.replace(/^#/, ""));
    if (h.has("cycle") && (D.cycles.includes(h.get("cycle")) || h.get("cycle") === "all")) state.cycle = h.get("cycle");
    state.q = h.get("q") || "";
    state.region = h.get("region") || "";
    state.school = h.get("school") || "";
    state.placement = h.get("placement") || "";
    state.sort = h.get("sort") || "rank";
    state.group = h.get("group") !== "0";
    state.fields = new Set((h.get("fields") || "").split(",").filter(Boolean));
  }
  function writeHash() {
    const h = new URLSearchParams();
    if (state.cycle !== D.cycles[0]) h.set("cycle", state.cycle);
    if (state.q) h.set("q", state.q);
    if (state.region) h.set("region", state.region);
    if (state.school) h.set("school", state.school);
    if (state.placement) h.set("placement", state.placement);
    if (state.sort !== "rank") h.set("sort", state.sort);
    if (!state.group) h.set("group", "0");
    if (state.fields.size) h.set("fields", [...state.fields].join(","));
    const s = h.toString();
    history.replaceState(null, "", s ? "#" + s : location.pathname + location.search);
  }

  // --------------------------------------------------------- helpers ----
  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const byCycle = (c) => state.cycle === "all" || c.cycle === state.cycle;
  const cycleCandidates = () => D.candidates.filter(byCycle);
  const cycleSchools = () => D.schools.filter(byCycle);

  function matches(c, ignore) {
    if (ignore !== "region" && state.region && c.region !== state.region) return false;
    if (ignore !== "school" && state.school && c.school_key !== state.school) return false;
    if (ignore !== "placement" && state.placement) {
      if (state.placement === "known" && !c.placement) return false;
      if (state.placement === "unknown" && c.placement) return false;
      if (!["known", "unknown"].includes(state.placement) && c.placement_type !== state.placement) return false;
    }
    if (ignore !== "fields" && state.fields.size) {
      for (const f of state.fields) if (!c.fields.includes(f)) return false;
    }
    if (ignore !== "q" && state.q) {
      const q = state.q.toLowerCase();
      const hay = [c.name, c.name_zh, c.school, c.school_zh, c.jmp, c.bio, c.placement, c.fields_raw, ...(c.fields || [])].join(" ").toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  }

  function sortCands(list) {
    const cmpRank = (a, b) => {
      const ra = a.rank ?? 9999, rb = b.rank ?? 9999;
      if (a.region !== b.region) return a.region === "美国区域" ? -1 : 1;
      if (ra !== rb) return ra - rb;
      if (a.school_order !== b.school_order) return a.school_order - b.school_order;
      return a.name.localeCompare(b.name, "zh");
    };
    if (state.sort === "name") return list.sort((a, b) => a.name.localeCompare(b.name, "zh") || cmpRank(a, b));
    if (state.sort === "school") return list.sort((a, b) => a.school.localeCompare(b.school) || cmpRank(a, b));
    return list.sort(cmpRank);
  }

  // -------------------------------------------------------- rendering ----
  function renderTabs() {
    const tabs = [...D.cycles, "all"];
    el.tabs.innerHTML = tabs.map((c) =>
      `<button type="button" data-cycle="${c}" class="${state.cycle === c ? "active" : ""}">${c === "all" ? "全部年度" : c}</button>`).join("");
  }

  function renderStats(list) {
    const all = cycleCandidates();
    const schools = new Set(list.map((c) => c.school_key));
    const placed = list.filter((c) => c.placement);
    const n = (t) => placed.filter((c) => c.placement_type === t).length;
    const deferred = n("Deferred");
    const pct = placed.length ? Math.round(100 * n("Faculty") / placed.length) : 0;
    const filtered = list.length !== all.length;
    el.stats.innerHTML = `
      <div class="stat"><div class="n">${list.length}</div><div class="l">候选人${filtered ? `（共 ${all.length}）` : ""}</div></div>
      <div class="stat"><div class="n">${schools.size}</div><div class="l">院校</div></div>
      <div class="stat"><div class="n">${placed.length}</div><div class="l">已知去向</div>
        <div class="sub">教职 ${n("Faculty")} · 博后 ${n("Postdoc")} · 业界/其他 ${n("Industry & Other")}${deferred ? ` · 延期 ${deferred}` : ""}</div></div>
      <div class="stat"><div class="n">${placed.length ? pct + "%" : "–"}</div><div class="l">已知去向中为教职</div></div>`;
  }


  function renderSelects() {
    // region
    const regions = [...new Set(cycleCandidates().map((c) => c.region))];
    el.region.innerHTML = `<option value="">全部地区</option>` + regions.map((r) => {
      const n = cycleCandidates().filter((c) => c.region === r && matches(c, "region")).length;
      return `<option value="${esc(r)}" ${state.region === r ? "selected" : ""}>${esc(REGION_LABEL[r] || r)} (${n})</option>`;
    }).join("");
    // school: keep source order (US by rank, then non-US)
    const seen = new Map();
    for (const s of cycleSchools()) if (!seen.has(s.key)) seen.set(s.key, s);
    const opts = [...seen.values()].filter((s) => !state.region || s.region === state.region).map((s) => {
      const n = cycleCandidates().filter((c) => c.school_key === s.key && matches(c, "school")).length;
      const rank = s.rank ? `#${s.rank} ` : "";
      return `<option value="${esc(s.key)}" ${state.school === s.key ? "selected" : ""}>${rank}${esc(s.name)}${s.name_zh ? "（" + esc(s.name_zh) + "）" : ""} (${n})</option>`;
    });
    el.school.innerHTML = `<option value="">全部院校</option>` + opts.join("");
    el.placement.value = state.placement;
    el.sort.value = state.sort;
    el.group.checked = state.group;
    el.q.value = state.q;
  }

  function renderChips() {
    const counts = {};
    for (const c of cycleCandidates()) if (matches(c, "fields")) for (const f of c.fields) counts[f] = (counts[f] || 0) + 1;
    const cats = D.field_categories.filter((f) => counts[f] || state.fields.has(f));
    cats.sort((a, b) => (counts[b] || 0) - (counts[a] || 0));
    el.chips.innerHTML = cats.map((f) =>
      `<button type="button" class="chip ${state.fields.has(f) ? "active" : ""}" data-field="${esc(f)}">${esc(f)}<span class="c">${counts[f] || 0}</span></button>`).join("");
  }

  function candRow(c) {
    const open = state.open.has(c.id);
    const tags = (c.fields || []).map((f) => `<span class="tag">${esc(f)}</span>`).join("") ||
      (c.fields_raw ? `<span class="tag raw">${esc(c.fields_raw)}</span>` : `<span class="none">–</span>`);
    const site = c.website ? `<a href="${esc(c.website)}" target="_blank" rel="noopener" title="${esc(c.website)}">主页 ↗</a>` : `<span class="none">–</span>`;
    const place = c.placement
      ? `<span class="badge ${esc((c.placement_type || "").split(" ")[0])}">${esc(PLACE_LABEL[c.placement_type] || c.placement_type)}</span><span class="txt">${esc(c.placement)}</span>`
      : `<span class="none">–</span>`;
    const yr = c.phd_year ? `<span class="yr">PhD ${c.phd_year}${c.info_missing ? " · 信息不详" : ""}</span>` : (c.info_missing ? `<span class="yr">信息不详</span>` : "");
    const schoolCell = `<span class="rank">${c.rank ? "#" + c.rank : ""}</span>${esc(c.school)}${state.cycle === "all" ? `<span class="yr" style="display:block;color:var(--muted);font-size:12px">${c.cycle}</span>` : ""}`;
    let html = `<tr class="cand ${open ? "open" : ""}" data-id="${esc(c.id)}">
      <td class="name">${esc(c.name)}${c.name_zh ? `<span class="zh">${esc(c.name_zh)}</span>` : ""}${yr}</td>
      <td class="school" data-label="院校">${schoolCell}</td>
      <td class="fields" data-label="领域">${tags}</td>
      <td class="jmp" data-label="JMP">${c.jmp ? esc(c.jmp) : `<span class="none">–</span>`}</td>
      <td class="links" data-label="主页">${site}</td>
      <td class="place" data-label="去向">${place}</td></tr>`;
    if (open) {
      const edu = (c.education || []).map((e) => `<li>${e.year} · ${esc(e.school)} · ${esc(e.degree)}</li>`).join("");
      html += `<tr class="detail"><td colspan="6"><div class="detail-inner">
        <div><h4>简介</h4><p>${esc(c.bio) || "<i>暂无</i>"}</p>
          ${c.fields_raw ? `<p class="src">研究兴趣（原文）：${esc(c.fields_raw)}</p>` : ""}
          ${c.website ? `<p class="src">个人主页：<a href="${esc(c.website)}" target="_blank" rel="noopener">${esc(c.website)}</a></p>` : ""}</div>
        <div><h4>教育经历</h4>${edu ? `<ul>${edu}</ul>` : "<p><i>未解析</i></p>"}
          <p class="src" style="margin-top:10px">来源：data/${esc(c.cycle)}.md · <a href="${CONFIG.repoUrl}/edit/main/data/${esc(c.cycle)}.md" target="_blank" rel="noopener">编辑此条目</a></p></div>
      </div></td></tr>`;
    }
    return html;
  }

  function renderTable(list) {
    const showEmptySchools = state.group && !state.q && !state.school && !state.placement && !state.fields.size;
    let html = "";
    if (state.group && state.sort === "rank") {
      // walk through schools in source order so schools with zero candidates (with notes) can be shown
      const schoolsInOrder = cycleSchools().filter((s) => !state.region || s.region === state.region);
      const byKey = new Map();
      for (const c of list) {
        const k = c.cycle + "|" + c.school_key;
        if (!byKey.has(k)) byKey.set(k, []);
        byKey.get(k).push(c);
      }
      const orderedKeys = new Set();
      for (const s of schoolsInOrder) orderedKeys.add(s.cycle + "|" + s.key);
      for (const s of schoolsInOrder) {
        const k = s.cycle + "|" + s.key;
        const cands = byKey.get(k) || [];
        if (!cands.length && !showEmptySchools) continue;
        const note = s.notes && s.notes.length ? `<span class="note">${esc(s.notes.join(" "))}</span>` : (cands.length ? "" : `<span class="note">暂无记录</span>`);
        html += `<tr class="group"><th colspan="6"><span class="rank">${s.rank ? "#" + s.rank : ""}</span>${esc(s.name)}${s.name_zh ? `<span class="zh">${esc(s.name_zh)}</span>` : ""}${state.cycle === "all" ? `<span class="zh">${s.cycle}</span>` : ""}${note}<span class="n">${cands.length} 人</span></th></tr>`;
        html += cands.map(candRow).join("");
      }
      // safety: any candidates whose school header wasn't in the list (shouldn't happen)
      for (const [k, cands] of byKey) if (!orderedKeys.has(k)) html += cands.map(candRow).join("");
    } else {
      html = list.map(candRow).join("");
    }
    el.tbody.innerHTML = html;
    el.empty.hidden = list.length > 0;
  }

  function render() {
    const list = sortCands(cycleCandidates().filter((c) => matches(c)));
    renderTabs();
    renderStats(list);
    renderSelects();
    renderChips();
    renderTable(list);
    const total = cycleCandidates().length;
    el.count.textContent = list.length === total ? `${total} 位候选人` : `筛选出 ${list.length} / ${total} 位候选人`;
    writeHash();
  }

  // ----------------------------------------------------------- events ----
  el.tabs.addEventListener("click", (e) => {
    const b = e.target.closest("button[data-cycle]");
    if (!b) return;
    state.cycle = b.dataset.cycle; state.school = ""; state.open.clear(); render();
  });
  let t;
  el.q.addEventListener("input", () => { clearTimeout(t); t = setTimeout(() => { state.q = el.q.value.trim(); render(); }, 120); });
  el.region.addEventListener("change", () => { state.region = el.region.value; state.school = ""; render(); });
  el.school.addEventListener("change", () => { state.school = el.school.value; render(); });
  el.placement.addEventListener("change", () => { state.placement = el.placement.value; render(); });
  el.sort.addEventListener("change", () => { state.sort = el.sort.value; render(); });
  el.group.addEventListener("change", () => { state.group = el.group.checked; render(); });
  el.reset.addEventListener("click", () => {
    state.q = ""; state.region = ""; state.school = ""; state.placement = ""; state.fields.clear(); state.sort = "rank"; render();
  });
  el.chips.addEventListener("click", (e) => {
    const b = e.target.closest("button[data-field]");
    if (!b) return;
    const f = b.dataset.field;
    state.fields.has(f) ? state.fields.delete(f) : state.fields.add(f);
    render();
  });
  el.tbody.addEventListener("click", (e) => {
    if (e.target.closest("a")) return;
    const tr = e.target.closest("tr.cand");
    if (!tr) return;
    const id = tr.dataset.id;
    state.open.has(id) ? state.open.delete(id) : state.open.add(id);
    render();
  });
  window.addEventListener("hashchange", () => { readHash(); render(); });

  readHash();
  render();
})();
